param([string]$RepoRoot = 'D:\servis-platform')
$ErrorActionPreference = 'Stop'
if (!(Test-Path -LiteralPath $RepoRoot)) { throw "RepoRoot not found: $RepoRoot" }
$backupRoot = Join-Path $RepoRoot ('tools\_backup\apply_m45_' + (Get-Date -Format 'yyyyMMdd-HHmmss'))
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
function Get-Rel([string]$Path) {
  if ([string]::IsNullOrWhiteSpace($Path)) { return $Path }
  $root = [System.IO.Path]::GetFullPath($RepoRoot)
  $full = [System.IO.Path]::GetFullPath($Path)
  if ($full.StartsWith($root, [System.StringComparison]::OrdinalIgnoreCase)) {
    $rel = $full.Substring($root.Length).TrimStart('\','/')
    if ([string]::IsNullOrWhiteSpace($rel)) { return '.' }
    return $rel
  }
  return $full
}

function Read-Utf8([string]$Path) {
  return ([System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8) -replace "`r`n", "`n")
}
function Backup-IfExists([string]$Path) {
  if (Test-Path -LiteralPath $Path) {
    $rel = (Get-Rel $Path)
    $bak = Join-Path $backupRoot $rel
    $bakDir = Split-Path -Parent $bak
    if ($bakDir -and !(Test-Path -LiteralPath $bakDir)) { New-Item -ItemType Directory -Force -Path $bakDir | Out-Null }
    Copy-Item -LiteralPath $Path -Destination $bak -Force
  }
}
function Write-Utf8([string]$Path, [string]$Content) {
  $dir = Split-Path -Parent $Path
  if ($dir -and !(Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  Backup-IfExists $Path
  [System.IO.File]::WriteAllText($Path, $Content, $Utf8NoBom)
  $rel = (Get-Rel $Path)
  Write-Host "OK wrote $rel"
}
function Assert-Contains([string]$RelPath, [string]$Needle, [string]$AppendBlock) {
  $path = Join-Path $RepoRoot $RelPath
  $txt = Read-Utf8 $path
  if ($txt.Contains($Needle)) {
    Write-Host "SKIP $RelPath already has marker"
    return
  }
  Write-Utf8 $path ($txt.TrimEnd("`r","`n") + "`r`n`r`n" + $AppendBlock.Trim() + "`r`n")
}
function Add-TextAfter([string]$RelPath, [string]$Needle, [string]$InsertBlock, [string]$Marker) {
  $path = Join-Path $RepoRoot $RelPath
  $txt = Read-Utf8 $path
  if ($txt.Contains($Marker)) {
    Write-Host "SKIP $RelPath already has marker"
    return
  }
  $idx = $txt.IndexOf($Needle)
  if ($idx -lt 0) { throw "Needle not found in $RelPath : $Needle" }
  $newTxt = $txt.Insert($idx + $Needle.Length, $InsertBlock)
  Write-Utf8 $path $newTxt
}
function Add-TextBefore([string]$RelPath, [string]$Needle, [string]$InsertBlock, [string]$Marker) {
  $path = Join-Path $RepoRoot $RelPath
  $txt = Read-Utf8 $path
  if ($txt.Contains($Marker)) {
    Write-Host "SKIP $RelPath already has marker"
    return
  }
  $idx = $txt.IndexOf($Needle)
  if ($idx -lt 0) { throw "Needle not found in $RelPath : $Needle" }
  $newTxt = $txt.Insert($idx, $InsertBlock)
  Write-Utf8 $path $newTxt
}

$files = @{}
$files['backend/src/ops/retentionBackupPolicy.js'] = ''
$files['backend/scripts/m45_retention_backup_check.js'] = ''
$files['docs/RUNBOOK_M45_RETENTION_BACKUP.md'] = '_EsSBrb250cm9sbMO8IG9ydGFtZGEgdGVzdCBlZGlsaXIK'
$files['docs/overlays/OVERLAY_NOTES_M45_RETENTION_BACKUP_2026-03-10.md'] = ''
$files['artifacts/.gitkeep'] = ''
$files['tools/pack_m45_retention_backup.ps1'] = ' '
$files['tools/check_m45_retention_backup_repo_contract.ps1'] = ''
$files['tools/backup_create_m45.ps1'] = ''
$files['tools/backup_restore_m45.ps1'] = ''

foreach ($entry in $files.GetEnumerator()) {
  try {
    $dest = Join-Path $RepoRoot $entry.Key
    $content = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($entry.Value))
    Write-Utf8 $dest $content
  } catch {
    Write-Host ("SKIP bad base64: " + $entry.Key)
  }
}

